window.AUTH=window.AUTH||{};window.AUTH["25-159"]={"d":"25-159","id":"2026/25-159","n":"Hoffmann v. WBI Energy Transmission, Inc.","briefs":[{"k":"petitioner","label":"Brief of petitioners Leonard W. Hoffmann, et al.","date":"2026-08-13","url":"https://www.supremecourt.gov/DocketPDF/25/25-159/418892/20260813103936272_1%20-%20Brief%20for%20Petitioners.pdf","side":"pet","n":61},{"k":"respondent","label":"Brief of respondent WBI Energy Transmission, Inc.","date":"2026-09-14","url":"https://www.supremecourt.gov/DocketPDF/25/25-159/424160/20260914155818845_25-159.Rsps%20Merits%20Br.pdf","side":"res","n":97},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2026-09-21","url":"https://www.supremecourt.gov/DocketPDF/25/25-159/425110/20260921193036019_Hoffmann_bsacUnitedStates.pdf","side":"us","n":61},{"k":"reply","label":"Reply of petitioners Leonard W. Hoffmann, et al.","date":"2026-10-14","url":"https://www.supremecourt.gov/DocketPDF/25/25-159/429463/20261014120213063_1%20-%20Reply%20Brief%20for%20Petitioners.pdf","side":"pet","n":36}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Agency Holding Corp. v. Malley-Duff & Assocs., Inc.","cite":"483 U.S. 143","y":1987,"id":"1986/86-497","sc":1,"sum":"In February 1978, petitioner Crown Life Insurance Co. terminated its relationship with its agent, respondent Malley-Duff & Associates (MalleyDuff), for failure to satisfy a production quota. Alleging, inter alia, that the real reason for the termination was petitioners' desire to acquire its lucrative territory, Malley-Duff brought suit in March 1981 under the Racketeer Influenced and Corrupt Organizations Act …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 27, 28, 29","1":"41","2":"25, 26","3":"2"}},{"t":"case","label":"Astoria Fed. Sav. & Loan Ass’n v. Solimino","cite":"501 U.S. 104","y":1991,"id":"1990/89-1895","sc":1,"sum":"Judicially unreviewed state administrative findings have no preclusive effect on age-discrimination proceedings in federal court. While well-established common-law principles, such as preclusion rules, are presumed to apply in the absence of a legislative intent to the contrary, Congress need not state expressly its intention to overcome a presumption of administrative estoppel. Clear-statement requirements are …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Biden v. Nebraska","cite":"600 U.S. 477","y":2023,"id":"2022/22-506","sc":1,"sum":"The Secretary of Education does not have authority under the Higher Education Relief Opportunities for Students Act of 2003 (HEROES Act) to establish a student loan forgiveness program that will cancel roughly $430 billion in debt principal and affect nearly all borrowers.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"32"}},{"t":"case","label":"Brown v. United States","cite":"263 U.S. 78","y":1923,"id":"scdb/1923-012","sc":1,"sum":"1. Where establishment of a reservoir under the Reclamation Act involved flooding part of a town, the United States had constitutional power to take by condemnation other private land near by, in the only practicable and available place, as a new townsite to which the buildings affected could be moved at the expense of the United States and new lots be provided in full or part satisfaction for those flooded.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"23, 24","1":"17","2":"27"}},{"t":"case","label":"Butner v. United States","cite":"440 U.S. 48","y":1979,"id":"1978/77-1410","sc":1,"sum":"Apart from certain special provisions, the Bankruptcy Act generally leaves the determination of property rights in the assets of a bankrupt's estate to BUTNER v. UNITED STATES","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43","1":"38"}},{"t":"case","label":"Campbell v. City of Haverhill","cite":"155 U.S. 610","y":1895,"id":"scdb/1894-066","sc":1,"sum":"Where a party excepts to a ruling of the court, but, not standing upon his exception, elects to proceed with the trial, he thereby waives it.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"24","3":"6"}},{"t":"case","label":"Cent. Neb. Pub. Power & Irrigation Dist. v. Fairchild","cite":"126 F.2d 302","y":1942,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/126/302/","by":{"0":"30","1":"18"}},{"t":"case","label":"Chattanooga Foundry & Pipe Works v. City of Atlanta","cite":"203 U.S. 390","y":1906,"id":"scdb/1906-040","sc":1,"sum":"By express provision of the act of July 2, 1890, 26 Stat. 209, a city is a person within the meaning of section 7 of that act, and can maintain an action against a party to a combination unlawful under the act by reason of which it has been forced to pay a price for an article above what rt is reasonably worth.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"City of Bismarck v. Thom","cite":"261 N.W.2d 640","y":1977,"court":"N.D.","url":"https://www.courtlistener.com/c/N.W.2d/261/640/","by":{"0":"47"}},{"t":"case","label":"Close Armstrong, LLC v. Trunkline Gas Co.","cite":"667 F. Supp. 3d 908","y":2023,"court":"N.D. Ind.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/667/908/","sum":"Noting recordation of pipeline deed.","sumSrc":"brief:0","by":{"0":"40"}},{"t":"case","label":"Columbia Gas Transmission Corp. v. Exclusive Nat. Gas Storage Easement","cite":"962 F.2d 1192","y":1992,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/962/1192/","by":{"0":"4"}},{"t":"case","label":"Columbia Gas Transmission, LLC v. Haas","cite":"341 F. Supp. 3d 607","y":2018,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/341/607/","by":{"0":"40"}},{"t":"case","label":"Dade County v. Brigham","cite":"47 So. 2d 602","y":1950,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%202d/47/602/","by":{"0":"47"}},{"t":"case","label":"Davies Warehouse Co. v. Bowles","cite":"321 U.S. 144","y":1944,"id":"scdb/1943-055","sc":1,"ar":1,"sum":"A public warehouse in California, the business of which is declared by the Constitution of the State to be that of a public utility and which is subject to comprehensive regulation (including the fixing of rates and charges) under the Public Utilities Act of the State, held a \"public utility\" within the meaning of the proviso of § 302 (c) of the federal Emergency Price Control Act, and thereby exempt from regulation …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17","1":"38","2":"20","3":"3, 4"}},{"t":"case","label":"Del. Riverkeeper Network v. Sec’y Pa. Dept. of Env’t Prot.","cite":"833 F.3d 360","y":2016,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/833/360/","sum":"Noting that states retain regulatory authority over interstate naturalgas pipelines under three different federal statutes.","sumSrc":"brief:0","by":{"0":"39"}},{"t":"case","label":"Feltz v. Cent. Neb. Pub. Power & Irrigation Dist.","cite":"124 F.2d 578","y":1942,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/124/578/","ar":1,"by":{"0":"30, 31","1":"18"}},{"t":"case","label":"Gas Transmission Nw., LLC v. FERC","cite":"157 F.4th 674","y":2025,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/157/674/","sum":"Describing pipeline approval and rate-setting process.","sumSrc":"brief:0","by":{"0":"41"}},{"t":"case","label":"Ga. Power Co. v. Sanders","cite":"617 F.2d 1112","y":1980,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/617/1112/","by":{"0":"3, 35","1":"13","2":"30"}},{"t":"case","label":"Grand River Dam Auth. v. Thompson","cite":"118 F.2d 242","y":1941,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/118/242/","by":{"0":"30"}},{"t":"case","label":"Gulf Interstate Gas Co. v. Garvin","cite":"303 S.W.2d 260","y":1957,"court":"Ky.","url":"https://www.courtlistener.com/c/S.W.2d/303/260/","by":{"0":"34","1":"25"}},{"t":"case","label":"Gundy v. United States","cite":"588 U.S. 128","y":2019,"id":"2018/17-6086","sc":1,"sum":"The Second Circuit’s judgment that 34 U. S. C. §20913(d)—which requires the Attorney General to apply the Sex Offender Registration and Notification Act’s registration requirements as soon as feasible to offenders convicted before the statute’s enactment—is not an unconstitutional delegation of legislative authority is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"32"}},{"t":"case","label":"Kirby Forest Indus., Inc. v. United States","cite":"467 U.S. 1","y":1984,"id":"1983/82-1994","sc":1,"sum":"Petitioner manufacturer of forest products owns substantial timberland in Texas. On August 21, 1978, after negotiations to acquire over 2,000 acres of this land for a national preserve had broken down, the United States filed a \"straight-condemnation\" complaint under 40 U. S. C. § 257. Shortly thereafter, the United States filed a notice of lis pendens, notifying the public of the institution of the proceeding. The …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14","1":"35, 36","2":"23"}},{"t":"case","label":"Library of Congress v. Shaw","cite":"478 U.S. 310","y":1986,"id":"1985/85-54","sc":1,"sum":"The no-interest rule applies here so as to preclude the award of increased compensation to respondent's counsel for the delay in receiving payment for his services.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15, 16, 20"}},{"t":"case","label":"Luber v. Milwaukee County","cite":"177 N.W.2d 380","y":1970,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W.2d/177/380/","by":{"0":"19"}},{"t":"case","label":"McCluny v. Silliman","cite":"3 Pet. 270","y":1830,"url":"https://www.courtlistener.com/c/Pet./3/270/","by":{"0":"24"}},{"t":"case","label":"McCulloch v. Maryland","cite":"4 Wheat. 316","y":1819,"url":"https://www.courtlistener.com/c/Wheat./4/316/","by":{"0":"21"}},{"t":"case","label":"Miss. River Transmission Corp. v. Tabor","cite":"757 F.2d 662","y":1985,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/757/662/","by":{"0":"3, 4"}},{"t":"case","label":"Monessen Sw. Ry. Co. v. Morgan","cite":"486 U.S. 330","y":1988,"id":"1987/86-1743","sc":1,"sum":"Appellee suffered a permanent back injury while working as a brakeman and conductor for appellant railroad. After returning to work in a less physically demanding position, appellee brought an action under the Federal Employers' Liability Act (FELA) in a Pennsylvania state court, alleging that his injury was attributable to appellant's negligence and that his future earning power had been impaired as a result of his …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35, 36","1":"37, 42","3":"4"}},{"t":"case","label":"O’Melveny & Myers v. FDIC","cite":"512 U.S. 79","y":1994,"id":"1993/93-489","sc":1,"sum":"Respondent Federal Deposit Insurance Corporation (FDIC), receiver for an insolvent California savings and loan (S&L), caused the S&L to make refunds to investors in certain fraudulent real estate syndications in which the S&L had been represented by petitioner law firm. The FDIC filed suit against petitioner in the Federal District Court and alleged state causes of action for professional negligence and breach of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"O’Sullivan v. Felix","cite":"233 U.S. 318","y":1914,"id":"scdb/1913-159","sc":1,"sum":"That an action depends upon, or arises under, the laws of the United States, does not preclude the application of the statute of limitations of the State. McLaine v. Rankin, 197 U. S. 154.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"24, 25"}},{"t":"case","label":"Olson v. United States","cite":"292 U.S. 246","y":1934,"id":"scdb/1933-123","sc":1,"sum":"1. By the Fifth and Fourteenth Amendments of the Federal Constitution, as also under Art. I, § 13 of the Constitution of Minnesota, appropriation of private property for a public use is forbidden unless a full and exact equivalent be returned to the owner.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"PennEast Pipeline Co. v. New Jersey","cite":"594 U.S. 482","y":2021,"id":"2020/19-1039","sc":1,"ar":7,"sum":"A certificate of public convenience and necessity issued by the Federal Energy Regulatory Commission pursuant to §717f(h) of the Natural Gas Act authorizes a private company to condemn all necessary rights-of-way, whether owned by private parties or States.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"1, 11, 13, 31, 44, 45, 46","1":"1, 3, 4, 5, 8, 11, 26, 27, 28, 33, 34, 35, 36, 38, 40, 41, 43, 47","2":"2, 4, 5, 10, 15, 17-20, 23, 24, 29, 32","3":"14, 15, 22"}},{"t":"case","label":"Pinewood Manor, Inc. v. Vt. Agency of Transp.","cite":"668 A.2d 653","y":1995,"court":"Vt.","url":"https://www.courtlistener.com/c/A.2d/668/653/","by":{"0":"19"}},{"t":"case","label":"Puntenney v. Iowa Utils. Bd.","cite":"928 N.W.2d 829","y":2019,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W.2d/928/829/","by":{"0":"34"}},{"t":"case","label":"Reconstruction Fin. Corp. v. Beaver County","cite":"328 U.S. 204","y":1946,"id":"scdb/1945-071","sc":1,"sum":"By § 10 of the Reconstruction Finance Corporation Act, Congress forbade States and local governments to tax personal property of the R. F. C. or its subsidiaries, but provided that their \"real property\" shall be subject to state and local taxation \"to the same extent according to its value as other real property is taxed.\" An R. F. C. subsidiary acquired certain land in Pennsylvania, erected buildings thereon, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 25, 43","1":"38","2":"26"}},{"t":"case","label":"Rodriguez v. FDIC","cite":"589 U.S. 132","y":2020,"url":"https://supreme.justia.com/cases/federal/us/589/132/","sc":1,"by":{"0":"43"}},{"t":"case","label":"Sabal Trail Transmission, LLC v. 18.27 Acres of Land","cite":"59 F.4th 1158","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/59/1158/","by":{"0":"4","1":"13"}},{"t":"case","label":"Sackett v. EPA","cite":"598 U.S. 651","y":2023,"id":"2022/21-454","sc":1,"sum":"The Clean Water Act extends only to wetlands that have a continuous surface connection with “waters” of the United States—i.e., with a relatively permanent body of water connected to traditional interstate navigable waters, 33 U. S. C. §1362(7)—making it difficult to determine where the water ends and the wetland begins.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"17","1":"38"}},{"t":"case","label":"Swango Homes, Inc. v. Columbia Gas Transmission Corp.","cite":"806 F. Supp. 180","y":1992,"court":"S.D. Ohio","url":"https://www.courtlistener.com/c/F.%20Supp./806/180/","by":{"0":"39"}},{"t":"case","label":"Tenn. Gas Pipeline Co. v. Permanent Easement for 7.053 Acres","cite":"931 F.3d 237","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/931/237/","by":{"0":"4","1":"13, 46","2":"16"}},{"t":"case","label":"Transcon. Gas Pipe Line Corp. v. Tieman","cite":"112 So. 2d 724","y":1959,"court":"La. Ct. App.","url":"https://www.courtlistener.com/c/So.%202d/112/724/","by":{"0":"34","1":"25"}},{"t":"case","label":"Transwestern Pipe Line Co. v. Yandell","cite":"367 P.2d 938","y":1961,"court":"N.M.","url":"https://www.courtlistener.com/c/P.2d/367/938/","by":{"0":"34","1":"25"}},{"t":"case","label":"Union Elec. Light & Power Co. v. Snyder Est. Co.","cite":"65 F.2d 297","y":1933,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/65/297/","by":{"0":"30"}},{"t":"case","label":"United States v. Beebe","cite":"127 U.S. 338","y":1888,"id":"scdb/1887-247","sc":1,"sum":"The Attorney General has authority, under the Constitution, to file a bill in equity in the name of the United States to set aside a patent of public land alleged to have been obtained by fraud or mistake, when the government has a direct interest in the tract patented, or is under an obligation respecting the relief invoked by the bill. The United States are not bound by any statute of limitations, nor barred by …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"United States v. Bodcaw Co.","cite":"440 U.S. 202","y":1979,"id":"1978/78-551","sc":1,"ar":4,"sum":"Respondent property owner's expenses in securing appraisals of the land involved in the United States' easement condemnation action held not to constitute part of the \"just compensation\" required by the Fifth Amendment for the taking of private property for public use. Since this litigation no more than reflects the rather typical situation where the landowner is dissatisfied with the Government's valuation, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47, 48","1":"9, 16, 17, 43","2":"2, 8, 12, 13, 19, 22","3":"8, 9, 13, 23"}},{"t":"case","label":"United States v. Carmack","cite":"329 U.S. 230","y":1946,"id":"scdb/1946-016","sc":1,"ar":3,"sum":"1. Under § 1 of the Condemnation Act of August 1, 1888, authorizing any officer of the Government authorized to procure real estate for the erection of a public building to acquire the same for the United States by condemnation \"whenever in his opinion it is necessary or advantageous to the Government to do so,\" and the Public Buildings Act of May 25, 1926, as amended, authorizing the Federal Works Administrator to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 20","1":"39, 40"}},{"t":"case","label":"United States v. Great Falls Mfg. Co.","cite":"112 U.S. 645","y":1884,"id":"scdb/1884-073","sc":1,"sum":"Where property to which the United States asserts no title, is taken by their officers or agents, pursuant to an act of Congress, as private property, for the public use, the government is under an implied obligation to-make just compensation to the owner.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"15","1":"3"}},{"t":"case","label":"United States v. Kimbell Foods, Inc.","cite":"440 U.S. 715","y":1979,"id":"1978/77-1359","sc":1,"ar":6,"sum":"These cases present the question whether contractual liens arising from certain federal loan programs take precedence over private liens, absent a federal statute that sets priorities. Resolution of this question requires determination of whether federal or state law governs the conflicting claims and, if federal law applies, whether a uniform priority rule should be fashioned or state commercial law should be …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 10, 37, 38, 40, 41, 42, 43","1":"8, 12, 45, 46, 47, 48, 49","2":"3, 7, 11, 32-34","3":"2, 13"}},{"t":"case","label":"United States v. Miller","cite":"317 U.S. 369","y":1943,"id":"scdb/1942-034","sc":1,"sum":"1. Where, from the date of its authorization by Act of Congress, a federal reclamation project included the relocation of a line of railroad, and a probable route was marked out over certain lands subsequently taken in eminent domain proceedings, it is proper,. in determining just compensation, to exclude from value as of the date of the taking such increase as occurred since the date of the authorization of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24","1":"2, 9, 15, 17, 18, 19, 20, 21, 22, 36, 38, 41","2":"14-17, 21","3":"9, 17"}},{"t":"case","label":"United States v. Nashville, Chattanooga & St. Louis Ry. Co.","cite":"118 U.S. 120","y":1886,"id":"scdb/1885-245","sc":1,"sum":"The statute of limitations of a State does not run against the right of action of the United States upon negotiable bonds and coupons of a railroad corporation, purchased by the United States before maturity as an investment of money received from the sale of lands ceded by an Indian tribe, and held in trust for the tribe, under a treaty.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"United States v. New Mexico","cite":"455 U.S. 720","y":1982,"id":"1981/80-702","sc":1,"ar":1,"sum":"The contractors, as independent taxable entities, are not protected by the Constitution's guarantee of federal supremacy, and hence are subject to the state taxes in question.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 22","1":"40","3":"9"}},{"t":"case","label":"United States v. Sargent","cite":"162 F. 81","y":1908,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./162/81/","by":{"0":"24"}},{"t":"case","label":"WBI Energy Transmission, Inc. v. 189.9 rods, more or less","cite":"2021 WL 1234585","y":2021,"court":"D.N.D. Apr. 1","by":{"0":"4, 5, 18"}},{"t":"case","label":"Winooski Hydroelectric Co. v. Five Acres of Land","cite":"769 F.2d 79","y":1985,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/769/79/","by":{"0":"3"}},{"t":"usc","label":"15 U.S.C. § 717f","url":"https://www.law.cornell.edu/uscode/text/15/717f","subs":["(h)","(c)","(d)","(e)"],"stext":{"head":"§717f. Construction, extension, or abandonment of facilities","paras":[[0,"(a) Extension or improvement of facilities on order of court; notice and hearing"],[0,"Whenever the Commission, after notice and opportunity for hearing, finds such action necessary or desirable in the public interest, it may by order direct a natural-gas company to extend or improve its transportation facilities, to establish physical connection of its transportation facilities with the facilities of, and sell natural gas to, any person or municipality engaged or legally authorized to engage in the local distribution of natural or artificial gas to the public, and for such purpose to extend its transportation facilities to communities immediately adjacent to such facilities or to territory served by such natural-gas company, if the Commission finds that no undue burden will be placed upon such natural-gas company thereby: Provided, That the Commission shall have no authority to compel the enlargement of transportation facilities for such purposes, or to compel such natural-gas company to establish physical connection or sell natural gas when to do so would impair its ability to render adequate service to its customers."],[0,"(b) Abandonment of facilities or services; approval of Commission"],[0,"No natural-gas company shall abandon all or any portion of its facilities subject to the jurisdiction of the Commission, or any service rendered by means of such facilities, without the permission and approval of the Commission first had and obtained, after due hearing, and a finding by the Commission that the available supply of natural gas is depleted to the extent that the continuance of service is unwarranted, or that the present or future public convenience or necessity permit such abandonment."],[0,"(c) Certificate of public convenience and necessity"],[0,"(1)(A) No natural-gas company or person which will be a natural-gas company upon completion of any proposed construction or extension shall engage in the transportation or sale of natural gas, subject to the jurisdiction of the Commission, or undertake the construction or extension of any facilities therefor, or acquire or operate any such facilities or extensions thereof, unless there is in force with respect to such natural-gas company a certificate of public convenience and necessity issued by the Commission authorizing such acts or operations: Provided, however, That if any such natural-gas company or predecessor in interest was bona fide engaged in transportation or sale of natural gas, subject to the jurisdiction of the Commission, on February 7, 1942, over the route or routes or within the area for which application is made and has so operated since that time, the Commission shall issue such certificate without requiring further proof that public convenience and necessity will be served by such operation, and without further proceedings, if application for such certificate is made to the Commission within ninety days after February 7, 1942. Pending the determination of any such application, the continuance of such operation shall be lawful."],[0,"(B) In all other cases the Commission shall set the matter for hearing and shall give such reasonable notice of the hearing thereon to all interested persons as in its judgment may be necessary under rules and regulations to be prescribed by the Commission; and the application shall be decided in accordance with the procedure provided in subsection (e) of this section and such certificate shall be issued or denied accordingly: Provided, however, That the Commission may issue a temporary certificate in cases of emergency, to assure maintenance of adequate service or to serve particular customers, without notice or hearing, pending the determination of an application for a certificate, and may by regulation exempt from the requirements of this section temporary acts or operations for which the issuance of a certificate will not be required in the public interest."],[0,"(2) The Commission may issue a certificate of public convenience and necessity to a natural-gas company for the transportation in interstate commerce of natural gas used by any person for one or more high-priority uses, as defined, by rule, by the Commission, in the case of—"],[1,"(A) natural gas sold by the producer to such person; and"],[1,"(B) natural gas produced by such person."],[0,"(d) Application for certificate of public convenience and necessity"],[0,"Application for certificates shall be made in writing to the Commission, be verified under oath, and shall be in such form, contain such information, and notice thereof shall be served upon such interested parties and in such manner as the Commission shall, by regulation, require."],[0,"(e) Granting of certificate of public convenience and necessity"],[0,"Except in the cases governed by the provisos contained in subsection (c)(1) of this section, a certificate shall be issued to any qualified applicant therefor, authorizing the whole or any part of the operation, sale, service, construction, extension, or acquisition covered by the application, if it is found that the applicant is able and willing properly to do the acts and to perform the service proposed and to conform to the provisions of this chapter and the requirements, rules, and regulations of the Commission thereunder, and that the proposed service, sale, operation, construction, extension, or acquisition, to the extent authorized by the certificate, is or will be required by the present or future public convenience and necessity; otherwise such application shall be denied. The Commission shall have the power to attach to the issuance of the certificate and to the exercise of the rights granted thereunder such reasonable terms and conditions as the public convenience and necessity may require."],[0,"(f) Determination of service area; jurisdiction of transportation to ultimate consumers"],[0,"(1) The Commission, after a hearing had upon its own motion or upon application, may determine the service area to which each authorization under this section is to be limited. Within such service area as determined by the Commission a natural-gas company may enlarge or extend its facilities for the purpose of supplying increased market demands in such service area without further authorization; and"],[0,"(2) If the Commission has determined a service area pursuant to this subsection, transportation to ultimate consumers in such service area by the holder of such service area determination, even if across State lines, shall be subject to the exclusive jurisdiction of the State commission in the State in which the gas is consumed. This section shall not apply to the transportation of natural gas to another natural gas company."],[0,"(g) Certificate of public convenience and necessity for service of area already being served"],[0,"Nothing contained in this section shall be construed as a limitation upon the power of the Commission to grant certificates of public convenience and necessity for service of an area already being served by another natural-gas company."],[0,"(h) Right of eminent domain for construction of pipelines, etc."],[0,"When any holder of a certificate of public convenience and necessity cannot acquire by contract, or is unable to agree with the owner of property to the compensation to be paid for, the necessary right-of-way to construct, operate, and maintain a pipe line or pipe lines for the transportation of natural gas, and the necessary land or other property, in addition to right-of-way, for the location of compressor stations, pressure apparatus, or other stations or equipment necessary to the proper operation of such pipe line or pipe lines, it may acquire the same by the exercise of the right of eminent domain in the district court of the United States for the district in which such property may be located, or in the State courts. The practice and procedure in any action or proceeding for that purpose in the district court of the United States shall conform as nearly as may be with the practice and procedure in similar action or proceeding in the courts of the State where the property is situated: Provided, That the United States district courts shall only have jurisdiction of cases when the amount claimed by the owner of the property to be condemned exceeds $3,000."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/717f?type=usc&year=mostrecent&link-type=html"},"head":"§717f. Construction, extension, or abandonment of facilities","tname":"Commerce and Trade","by":{"0":"1, 2, 3, 13, 14, 30, 39, 48","2":"4, 4, 4, 4, 2, 5, 6, 9-11, 16-21, 23-32","3":"2, 5, 7, 11, 13, 14, 15, 16, 17, 22"}},{"t":"usc","label":"16 U.S.C. § 814","url":"https://www.law.cornell.edu/uscode/text/16/814","stext":{"head":"§814. Exercise by licensee of power of eminent domain","paras":[[0,"When any licensee cannot acquire by contract or pledges an unimproved dam site or the right to use or damage the lands or property of others necessary to the construction, maintenance, or operation of any dam, reservoir, diversion structure, or the works appurtenant or accessory thereto, in conjunction with any improvement which in the judgment of the commission is desirable and justified in the public interest for the purpose of improving or developing a waterway or waterways for the use or benefit of interstate or foreign commerce, it may acquire the same by the exercise of the right of eminent domain in the district court of the United States for the district in which such land or other property may be located, or in the State courts. The practice and procedure in any action or proceeding for that purpose in the district court of the United States shall conform as nearly as may be with the practice and procedure in similar action or proceeding in the courts of the State where the property is situated: Provided, That United States district courts shall only have jurisdiction of cases when the amount claimed by the owner of the property to be condemned exceeds $3,000 1 Provided further, That no licensee may use the right of eminent domain under this section to acquire any lands or other property that, prior to October 24, 1992, were owned by a State or political subdivision thereof and were part of or included within any public park, recreation area or wildlife refuge established under State or local law. In the case of lands or other property that are owned by a State or political subdivision and are part of or included within a public park, recreation area or wildlife refuge established under State or local law on or after October 24, 1992, no licensee may use the right of eminent domain under this section to acquire such lands or property unless there has been a public hearing held in the affected community and a finding by the Commission, after due consideration of expressed public views and the recommendations of the State or political subdivision that owns the lands or property, that the license will not interfere or be inconsistent with the purposes for which such lands or property are owned."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/814?type=usc&year=mostrecent&link-type=html"},"head":"§814. Exercise by licensee of power of eminent domain","tname":"Conservation","by":{"0":"2, 30","1":"5","2":"5, 6, 27"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"40 U.S.C. § 3114","url":"https://www.law.cornell.edu/uscode/text/40/3114","stext":{"head":"§3114. Declaration of taking","paras":[[0,"(a) Filing and Content.—In any proceeding in any court of the United States outside of the District of Columbia brought by and in the name of the United States and under the authority of the Federal Government to acquire land, or an easement or right of way in land, for the public use, the petitioner may file, with the petition or at any time before judgment, a declaration of taking signed by the authority empowered by law to acquire the land described in the petition, declaring that the land is taken for the use of the Government. The declaration of taking shall contain or have annexed to it—"],[1,"(1) a statement of the authority under which, and the public use for which, the land is taken;"],[1,"(2) a description of the land taken that is sufficient to identify the land;"],[1,"(3) a statement of the estate or interest in the land taken for public use;"],[1,"(4) a plan showing the land taken; and"],[1,"(5) a statement of the amount of money estimated by the acquiring authority to be just compensation for the land taken."],[0,"(b) Vesting of Title.—On filing the declaration of taking and depositing in the court, to the use of the persons entitled to the compensation, the amount of the estimated compensation stated in the declaration—"],[1,"(1) title to the estate or interest specified in the declaration vests in the Government;"],[1,"(2) the land is condemned and taken for the use of the Government; and"],[1,"(3) the right to just compensation for the land vests in the persons entitled to the compensation."],[0,"(c) Compensation.—"],[1,"(1) Determination and award.—Compensation shall be determined and awarded in the proceeding and established by judgment. The judgment shall include interest, in accordance with section 3116 of this title, on the amount finally awarded as the value of the property as of the date of taking and shall be awarded from that date to the date of payment. Interest shall not be allowed on as much of the compensation as has been paid into the court. Amounts paid into the court shall not be charged with commissions or poundage."],[1,"(2) Order to pay.—On application of the parties in interest, the court may order that any part of the money deposited in the court be paid immediately for or on account of the compensation to be awarded in the proceeding."],[1,"(3) Deficiency judgment.—If the compensation finally awarded is more than the amount of money received by any person entitled to compensation, the court shall enter judgment against the Government for the amount of the deficiency."],[0,"(d) Authority of Court.—On the filing of a declaration of taking, the court—"],[1,"(1) may fix the time within which, and the terms on which, the parties in possession shall be required to surrender possession to the petitioner; and"],[1,"(2) may make just and equitable orders in respect of encumbrances, liens, rents, taxes, assessments, insurance, and other charges."],[0,"(e) Vesting Not Prevented or Delayed.—An appeal or a bond or undertaking given in a proceeding does not prevent or delay the vesting of title to land in the Government."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/40/3114?type=usc&year=mostrecent&link-type=html"},"head":"§3114. Declaration of taking","tname":"Public Buildings, Property, and Works","by":{"0":"14","1":"37"}},{"t":"usc","label":"42 U.S.C. § 4601","url":"https://www.law.cornell.edu/uscode/text/42/4601","stext":{"head":"§4601. Definitions","paras":[[0,"As used in this chapter—"],[0,"(1) The term \"Federal agency\" means any department, agency, or instrumentality in the executive branch of the Government, any wholly owned Government corporation, the Architect of the Capitol, the Federal Reserve banks and branches thereof, and any person who has the authority to acquire property by eminent domain under Federal law."],[0,"(2) The term \"State\" means any of the several States of the United States, the District of Columbia, the Commonwealth of Puerto Rico, any territory or possession of the United States, the Trust Territory of the Pacific Islands, and any political subdivision thereof."],[0,"(3) The term \"State agency\" means any department, agency, or instrumentality of a State or of a political subdivision of a State, any department, agency, or instrumentality of 2 or more States or of 2 or more political subdivisions of a State or States, and any person who has the authority to acquire property by eminent domain under State law."],[0,"(4) The term \"Federal financial assistance\" means a grant, loan, or contribution provided by the United States, except any Federal guarantee or insurance, any interest reduction payment to an individual in connection with the purchase and occupancy of a residence by that individual, and any annual payment or capital loan to the District of Columbia."],[0,"(5) The term \"person\" means any individual, partnership, corporation, or association."],[0,"(6)(A) The term \"displaced person\" means, except as provided in subparagraph (B)—"],[1,"(i) any person who moves from real property, or moves his personal property from real property—"],[2,"(I) as a direct result of a written notice of intent to acquire or the acquisition of such real property in whole or in part for a program or project undertaken by a Federal agency or with Federal financial assistance; or"],[2,"(II) on which such person is a residential tenant or conducts a small business, a farm operation, or a business defined in paragraph (7)(D), as a direct result of rehabilitation, demolition, or such other displacing activity as the lead agency may prescribe, under a program or project undertaken by a Federal agency or with Federal financial assistance in any case in which the head of the displacing agency determines that such displacement is permanent; and"],[1,"(ii) solely for the purposes of sections 4622(a) and (b) and 4625 of this title, any person who moves from real property, or moves his personal property from real property—"],[2,"(I) as a direct result of a written notice of intent to acquire or the acquisition of other real property, in whole or in part, on which such person conducts a business or farm operation, for a program or project undertaken by a Federal agency or with Federal financial assistance; or"],[2,"(II) as a direct result of rehabilitation, demolition, or such other displacing activity as the lead agency may prescribe, of other real property on which such person conducts a business or a farm operation, under a program or project undertaken by a Federal agency or with Federal financial assistance where the head of the displacing agency determines that such displacement is permanent."],[0,"(B) The term \"displaced person\" does not include—"],[1,"(i) a person who has been determined, according to criteria established by the head of the lead agency, to be either in unlawful occupancy of the displacement dwelling or to have occupied such dwelling for the purpose of obtaining assistance under this chapter;"],[1,"(ii) in any case in which the displacing agency acquires property for a program or project, any person (other than a person who was an occupant of such property at the time it was acquired) who occupies such property on a rental basis for a short term or a period subject to termination when the property is needed for the program or project."],[0,"(7) The term \"business\" means any lawful activity, excepting a farm operation, conducted primarily—"],[1,"(A) for the purchase, sale, lease and rental of personal and real property, and for the manufacture, processing, or marketing of products, commodities, or any other personal property;"],[1,"(B) for the sale of services to the public;"],[1,"(C) by a nonprofit organization; or"],[1,"(D) solely for the purposes of section 4622 of this title, for assisting in the purchase, sale, resale, manufacture, processing, or marketing of products, commodities, personal property, or services by the erection and maintenance of an outdoor advertising display or displays, whether or not such display or displays are located on the premises on which any of the above activities are conducted."],[0,"(8) The term \"farm operation\" means any activity conducted solely or primarily for the production of one or more agricultural products or commodities, including timber, for sale or home use, and customarily producing such products or commodities in sufficient quantity to be capable of contributing materially to the operator's support."],[0,"(9) The term \"mortgage\" means such classes of liens as are commonly given to secure advances on, or the unpaid purchase price of, real property, under the laws of the State in which the real property is located, together with the credit instruments, if any, secured thereby."],[0,"(10) The term \"comparable replacement dwelling\" means any dwelling that is (A) decent, safe, and sanitary; (B) adequate in size to accommodate the occupants; (C) within the financial means of the displaced person; (D) functionally equivalent; (E) in an area not subject to unreasonable adverse environmental conditions; and (F) in a location generally not less desirable than the location of the displaced person's dwelling with respect to public utilities, facilities, services, and the displaced person's place of employment."],[0,"(11) The term \"displacing agency\" means any Federal agency carrying out a program or project, and any State, State agency, or person carrying out a program or project with Federal financial assistance, which causes a person to be a displaced person."],[0,"(12) The term \"lead agency\" means the Department of Transportation."],[0,"(13) The term \"appraisal\" means a written statement independently and impartially prepared by a qualified appraiser setting forth an opinion of defined value of an adequately described property as of a specific date, supported by the presentation and analysis of relevant market information."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/4601?type=usc&year=mostrecent&link-type=html"},"head":"§4601. Definitions","tname":"The Public Health and Welfare","by":{"0":"36","2":"13"}},{"t":"usc","label":"16 U.S.C. § 824p","url":"https://www.law.cornell.edu/uscode/text/16/824p","subs":["(f)"],"stext":{"head":"§824p. Siting of interstate electric transmission facilities","paras":[[0,"(a) Designation of national interest electric transmission corridors"],[0,"(1) Not later than 1 year after August 8, 2005, and every 3 years thereafter, the Secretary of Energy (referred to in this section as the \"Secretary\"), in consultation with affected States and Indian Tribes, shall conduct a study of electric transmission capacity constraints and congestion."],[0,"(2) Not less frequently than once every 3 years, the Secretary, after considering alternatives and recommendations from interested parties (including an opportunity for comment from affected States and Indian Tribes), shall issue a report, based on the study under paragraph (1) or other information relating to electric transmission capacity constraints and congestion, which may designate as a national interest electric transmission corridor any geographic area that—"],[1,"(i) 1 is experiencing electric energy transmission capacity constraints or congestion that adversely affects consumers; or"],[1,"(ii) 2 is expected to experience such energy transmission capacity constraints or congestion."],[0,"(3) Not less frequently than once every 3 years, the Secretary, in conducting the study under paragraph (1) and issuing the report under paragraph (2), shall consult with any appropriate regional entity referred to in section 824o of this title."],[0,"(4) In determining whether to designate a national interest electric transmission corridor under paragraph (2), the Secretary may consider whether—"],[1,"(A) the economic vitality and development of the corridor, or the end markets served by the corridor, may be constrained by lack of adequate or reasonably priced electricity;"],[1,"(B)(i) economic growth in the corridor, or the end markets served by the corridor, may be jeopardized by reliance on limited sources of energy; and"],[1,"(ii) a diversification of supply is warranted;"],[1,"(C) the energy independence or energy security of the United States would be served by the designation;"],[1,"(D) the designation would be in the interest of national energy policy;"],[1,"(E) the designation would enhance national defense and homeland security;"],[1,"(F) the designation would enhance the ability of facilities that generate or transmit firm or intermittent energy to connect to the electric grid;"],[1,"(G) the designation—"],[2,"(i) maximizes existing rights-of-way; and"],[2,"(ii) avoids and minimizes, to the maximum extent practicable, and offsets to the extent appropriate and practicable, sensitive environmental areas and cultural heritage sites; and"],[1,"(H) the designation would result in a reduction in the cost to purchase electric energy for consumers."],[0,"(b) Construction permit"],[0,"Except as provided in subsection (i), the Commission may, after notice and an opportunity for hearing, issue one or more permits for the construction or modification of electric transmission facilities in a national interest electric transmission corridor designated by the Secretary under subsection (a) if the Commission finds that—"],[1,"(1)(A) a State in which the transmission facilities are to be constructed or modified does not have authority to—"],[2,"(i) approve the siting of the facilities; or"],[2,"(ii) consider the interstate benefits or interregional benefits expected to be achieved by the proposed construction or modification of transmission facilities in the State;"],[1,"(B) the applicant for a permit is a transmitting utility under this chapter but does not qualify to apply for a permit or siting approval for the proposed project in a State because the applicant does not serve end-use customers in the State; or"],[1,"(C) a State commission or other entity that has authority to approve the siting of the facilities—"],[2,"(i) has not made a determination on an application seeking approval pursuant to applicable law by the date that is 1 year after the later of—"],[3,"(I) the date on which the application was filed; and"],[3,"(II) the date on which the relevant national interest electric transmission corridor was designated by the Secretary under subsection (a);"],[2,"(ii) has conditioned its approval in such a manner that the proposed construction or modification will not significantly reduce transmission capacity constraints or congestion in interstate commerce or is not economically feasible; or"],[2,"(iii) has denied an application seeking approval pursuant to applicable law;"],[1,"(2) the facilities to be authorized by the permit will be used for the transmission of electric energy in interstate commerce;"],[1,"(3) the proposed construction or modification is consistent with the public interest;"],[1,"(4) the proposed construction or modification will significantly reduce transmission congestion in interstate commerce and protects or benefits consumers;"],[1,"(5) the proposed construction or modification is consistent with sound national energy policy and will enhance energy independence; and"],[1,"(6) the proposed modification will maximize, to the extent reasonable and economical, the transmission capabilities of existing towers or structures."],[0,"(c) Permit applications"],[0,"(1) Permit applications under subsection (b) shall be made in writing to the Commission."],[0,"(2) The Commission shall issue rules specifying—"],[1,"(A) the form of the application;"],[1,"(B) the information to be contained in the application; and"],[1,"(C) the manner of service of notice of the permit application on interested persons."],[0,"(d) Comments"],[0,"In any proceeding before the Commission under subsection (b), the Commission shall afford each State in which a transmission facility covered by the permit is or will be located, each affected Federal agency and Indian tribe, private property owners, and other interested persons, a reasonable opportunity to present their views and recommendations with respect to the need for and impact of a facility covered by the permit."],[0,"(e) Rights-of-way"],[0,"(1) In the case of a permit under subsection (b) for electric transmission facilities to be located on property other than property owned by the United States or a State, if the permit holder cannot acquire by contract, or is unable to agree with the owner of the property to the compensation to be paid for, the necessary right-of-way to construct or modify, and operate and maintain, the transmission facilities and, in the determination of the Commission, the permit holder has made good faith efforts to engage with landowners and other stakeholders early in the applicable permitting process, the permit holder may acquire the right-of-way by the exercise of the right of eminent domain in the district court of the United States for the district in which the property concerned is located, or in the appropriate court of the State in which the property is located."],[0,"(2) Any right-of-way acquired under paragraph (1) shall be used exclusively for the construction or modification of electric transmission facilities within a reasonable period of time after the acquisition."],[0,"(3) The practice and procedure in any action or proceeding under this subsection in the district court of the United States shall conform as nearly as practicable to the practice and procedure in a similar action or proceeding in the courts of the State in which the property is located."],[0,"(4) Nothing in this subsection shall be construed to authorize the use of eminent domain to acquire a right-of-way for any purpose other than the construction, modification, operation, or maintenance of electric transmission facilities and related facilities. The right-of-way cannot be used for any other purpose, and the right-of-way shall terminate upon the termination of the use for which the right-of-way was acquired."],[0,"(f) Compensation"],[0,"(1) Any right-of-way acquired pursuant to subsection (e) shall be considered a taking of private property for which just compensation is due."],[0,"(2) Just compensation shall be an amount equal to the fair market value (including applicable severance damages) of the property taken on the date of the exercise of eminent domain authority."],[0,"(g) State law"],[0,"Nothing in this section precludes any person from constructing or modifying any transmission facility in accordance with State law."],[0,"(h) Coordination of Federal authorizations for transmission facilities"],[0,"(1) In this subsection:"],[1,"(A) The term \"Federal authorization\" means any authorization required under Federal law in order to site a transmission facility."],[1,"(B) The term \"Federal authorization\" includes such permits, special use authorizations, certifications, opinions, or other approvals as may be required under Federal law in order to site a transmission facility."],[0,"(2) The Department of Energy shall act as the lead agency for purposes of coordinating all applicable Federal authorizations and related environmental reviews of the facility."],[0,"(3) To the maximum extent practicable under applicable Federal law, the Secretary shall coordinate the Federal authorization and review process under this subsection with any Indian tribes, multistate entities, and State agencies that are responsible for conducting any separate permitting and environmental reviews of the facility, to ensure timely and efficient review and permit decisions."],[0,"(4)(A) As head of the lead agency, the Secretary, in consultation with agencies responsible for Federal authorizations and, as appropriate, with Indian tribes, multistate entities, and State agencies that are willing to coordinate their own separate permitting and environmental reviews with the Federal authorization and environmental reviews, shall establish prompt and binding intermediate milestones and ultimate deadlines for the review of, and Federal authorization decisions relating to, the proposed facility."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/824p?type=usc&year=mostrecent&link-type=html"},"head":"§824p. Siting of interstate electric transmission facilities","tname":"Conservation","by":{"0":"35, 36","2":"31, 30, 30"}},{"t":"rule","label":"Fed. R. Civ. P. 71.1","url":"https://www.law.cornell.edu/rules/frcp/rule_71.1","by":{"0":"3"}},{"t":"case","label":"Almota Farmers Elevator & Warehouse Co. v. United States","cite":"409 U.S. 470","y":1973,"id":"1972/71-951","sc":1,"sum":"In a condemnation proceeding, the concept of \"just compensation\" is measured by what a willing buyer would have paid for the improvements, taking into account the possibility that the lease might be renewed as well as that it might not. Pp. 473-478. 450 F. 2d 125, reversed and District Court judgment reinstated.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Ardestani v. INS","cite":"502 U.S. 129","y":1991,"id":"1991/90-1141","sc":1,"sum":"Administrative deportation proceedings are not adversary adjudications \"under section 554\" and thus do not fall within the category of proceedings for which the EAJA has waived sovereign immunity and authorized the award of attorney's fees and costs.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Baker Botts LLP v. ASARCO LLC","cite":"576 U.S. 121","y":2015,"id":"2014/14-103","sc":1,"sum":"The Court held that the Bankruptcy Code does not provide an explicit statutory exception to the American rule of attorney fees—that each litigant pays for his own attorney’s fees.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Bartenwerfer v. Buckley","cite":"598 U.S. 69","y":2023,"id":"2022/21-908","sc":1,"sum":"Pursuant to §523(a)(2)(A) of the Bankruptcy Code, a debtor like Kate Bartenwerfer who is liable for her partner’s fraud cannot discharge that debt in bankruptcy, regardless of her own culpability.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"18"}},{"t":"case","label":"Berman v. Parker","cite":"348 U.S. 26","y":1954,"id":"1940-1955/348us26","sc":1,"sum":"The Court found that the Fifth Amendment does not limit Congress' power to seize private property with just compensation to any specific purpose.","sumSrc":"Oyez","by":{"1":"3"}},{"t":"case","label":"Bloate v. United States","cite":"559 U.S. 196","y":2010,"id":"2009/08-728","sc":1,"sum":"The Court held that the time granted to prepare pretrial motions is not automatically granted exclusion from the Speedy Trial Act's 70-day time limit.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Board of Comm’rs of Jackson Cnty. v. United States","cite":"308 U.S. 343","y":1939,"id":"scdb/1939-014","sc":1,"sum":"Argument for Petitioner.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18","2":"27","3":"2, 14"}},{"t":"case","label":"Campbell v. United States","cite":"138 Fed. Cl. 65","y":2018,"url":"https://www.courtlistener.com/c/Fed.%20Cl./138/65/","by":{"1":"30"}},{"t":"case","label":"Campbell v. United States","cite":"266 U.S. 368","y":1924,"id":"scdb/1924-020","sc":1,"by":{"1":"16, 31"}},{"t":"case","label":"Carey v. Piphus","cite":"435 U.S. 247","y":1978,"id":"1977/76-1149","sc":1,"sum":"The Court held that the purpose of the Civil Rights Act of 1871 is to compensate people for injuries caused by the deprivation of civil rights, which means that compensation cannot occur without proof of injury. However, the definition of injury must be adapted to fit the civil rights in question.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Cherokee Nation v. Southern Kan. Ry.","cite":"135 U.S. 641","y":1890,"id":"scdb/1889-250","sc":1,"sum":"The act of Congress of July 4, 1884, 23 Stat. 73, c. 179, granting a right of way through the Indian Territory to the Southern Kansas Railway Company, for a railroad, telegraph and telephone line, is a valid exercise of the power of Congress to regulate commerce among the several States and with the Indian tribes.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"3, 20, 27, 37, 39","3":"11"}},{"t":"case","label":"Chesapeake & Ohio Ry. v. Kelly","cite":"241 U.S. 485","y":1916,"id":"scdb/1915-176","sc":1,"sum":"Minneapolis & St. Louis R. R. v. Bombolis, ante, p. 211, followed to.the effect that the Seventh Amendment does not apply to actions under the Employers’ Liability Act brought in the state courts.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"42","3":"5"}},{"t":"case","label":"City of Milwaukee v. Illinois & Michigan","cite":"451 U.S. 304","y":1981,"id":"1980/79-408","sc":1,"sum":"In original proceedings brought by respondent State of Illinois, alleging that petitioners-the city of Milwaukee, its Sewerage Commission, and Milwaukee County's Metropolitan Sewerage Commission-and other Wisconsin cities were polluting Lake Michigan because of overflows of untreated sewage from their sewer systems and discharges of inadequately treated sewage from their treatment plants, this Court recognized the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Comparet v. United States","cite":"164 F.2d 452","y":1947,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/164/452/","by":{"1":"20"}},{"t":"case","label":"County of Maui v. Hawaii Wildlife Fund","cite":"590 U.S. 165","y":2020,"id":"2019/18-260","sc":1,"sum":"The Court held the Clean Water Act requires a permit when pollutants originate from a point source but are conveyed to navigable waters by a nonpoint source, such as groundwater, if the conveyance is the \"functional equivalent\" of a direct discharge.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Danforth v. United States","cite":"308 U.S. 271","y":1939,"id":"scdb/1939-027","sc":1,"sum":"1. Under § 4 of the Flood Control Act of May 15, 1928, the Secretary of War may agree to purchase easements for flowage purposes, subject to the perfecting of the title through condemnation.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"DelCostello v. Int’l Bhd. of Teamsters","cite":"462 U.S. 151","y":1983,"id":"1982/81-2386","sc":1,"sum":"The issue in each of these cases is what statute of limitations applies in an employee suit against an employer and a union, alleging the employer's breach of a collective-bargaining agreement and the union's breach of its duty of fair representation by mishandling the ensuing grievance or arbitration proceedings. United Parcel Service, Inc. v. Mitchell, 451 U. S. 56, held in a similar suit that an employee's claim …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43","2":"25"}},{"t":"case","label":"Dohany v. Rogers","cite":"281 U.S. 362","y":1930,"id":"scdb/1929-051","sc":1,"sum":"that 'the taking of private land to he so exchanged is a taking for a 'public purpose.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16","2":"12"}},{"t":"case","label":"Dooley v. Korean Air Lines","cite":"524 U.S. 116","y":1998,"id":"1997/97-704","sc":1,"sum":"The Court held that \"[b]ecause Congress has chosen not to authorize a survival action for a decedent's pre-death pain and suffering, there can be no general maritime survival action for such damages.\" Justice Thomas wrote for the Court that the \"comprehensive scope of DOHSA is confirmed by its survival provision, which limits the recovery in such cases to the pecuniary losses suffered by surviving relatives.","sumSrc":"Oyez","by":{"1":"42","3":"4, 5"}},{"t":"case","label":"F.D. Rich Co. v. Industrial Lumber Co.","cite":"417 U.S. 116","y":1974,"id":"1973/72-1382","sc":1,"sum":"Petitioner F. D. Rich Co., the prime contractor on a federal housing project in California, had two separate contracts for the project with Cerpac Co., one contract being for Cerpac to select, modify, detail, and install all custom millwork and the other being for Cerpac to supply all exterior plywood. Cerpac in turn ordered the lumber called for under the plywood contract from respondent. When Rich needed plywood …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41","3":"5"}},{"t":"case","label":"Hardt v. Reliance Standard Life Ins.","cite":"560 U.S. 242","y":2010,"id":"2009/09-448","sc":1,"sum":"The Court held that a party is entitled to attorneys' fees pursuant to Section 502(g)(1) of the Employee Retirement Income Security Act when an ERISA violation has occurred.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Hippely v. United States","cite":"173 Fed. Cl. 389","y":2024,"url":"https://www.courtlistener.com/c/Fed.%20Cl./173/389/","by":{"1":"30"}},{"t":"case","label":"John Hancock Mut. Life Ins. v. Casey","cite":"147 F.2d 762","y":1945,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/147/762/","by":{"1":"20"}},{"t":"case","label":"Kamen v. Kemper Fin. Servs., Inc.","cite":"500 U.S. 90","y":1991,"id":"1990/90-516","sc":1,"sum":"A court entertaining a derivative action under the ICA must apply the demand futility exception as it is defined by the law of the State of incorporation.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"49"}},{"t":"case","label":"Kimble v. Marvel Ent., LLC","cite":"576 U.S. 446","y":2015,"id":"2014/13-720","sc":1,"sum":"The Court determined that its earlier decision in Brulotte v. Thys Co. , which held that a patentee cannot continue to receive royalties after the expiration of the patent, should be upheld.","sumSrc":"Oyez","by":{"1":"2, 31"}},{"t":"case","label":"Kohl v. United States","cite":"91 U.S. 367","y":1875,"id":"scdb/1875-135","sc":1,"ar":3,"sum":"This was a proceeding instituted by the United States to appropriate a parcel of land in the city of Cincinnati as a site for a post-office and other, public uses.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"3, 14, 35, 41","2":"9, 14, 15, 25"}},{"t":"case","label":"L. Vogelstein & Co. v. United States","cite":"262 U.S. 337","y":1923,"id":"scdb/1922-195","sc":1,"sum":"Just compensation for copper taken by the United States for war purposes under the Act of June 3, 1916, c. 134, §§ 120, 123, 39 Stat. 215, is to be measured by the market value of the copper at the time of the taking, and not by higher prices which the owner was obliged to pay under long time purchase contracts. P. 340. 56 Ct. Clms. 362, affirmed; motion to remand denied. APPEAL from a judgment of the Court of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Luxton v. North River Bridge Co.","cite":"153 U.S. 525","y":1894,"id":"scdb/1893-251","sc":1,"sum":"—Decided May 14, 1894.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"4","2":"15"}},{"t":"case","label":"Maine Cmty. Health Options v. United States","cite":"590 U.S. 296","y":2020,"id":"2019/18-1023","sc":1,"sum":"The Court held that the federal government has an obligation to pay the insurance carriers in this case for losses incurred under the \"Risk Corridors\" program of the Affordable Care Act as a result of their participation in the health care marketplace.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Memphis Cmty. Sch. Dist. v. Stachura","cite":"477 U.S. 299","y":1986,"id":"1985/85-410","sc":1,"sum":"Damages based on the abstract \"value\" or \"importance\" of constitutional rights are not a permissible element of compensatory damages in § 1983 cases.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Mississippi & Rum River Boom Co. v. Patterson","cite":"98 U.S. 403","y":1878,"id":"scdb/1878-111","sc":1,"sum":"The plaintiff is a corporation created by the laws of Minnesota, known as the Mississippi and Rum River Boom Company, and the defendant is a citizen of the State of Illinois.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"3, 14","2":"15"}},{"t":"case","label":"Mitchell v. United States","cite":"267 U.S. 341","y":1925,"id":"scdb/1924-103","sc":1,"by":{"1":"16"}},{"t":"case","label":"Mobil Oil Corp. v. Higginbotham","cite":"436 U.S. 618","y":1978,"id":"1977/76-1726","sc":1,"sum":"In an action for wrongful death on the high seas, the measure of damages is governed by the Death on the High Seas Act, 46 U. S. C. § 762, which limits a decedent's survivors' recovery to their \"pecuniary loss,\" and hence the survivors are not entitled to recover additional damages under general maritime law for \"loss of society.\" Pp. 620-626. 545 F. 2d 422, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Monongahela Nav. Co. v. United States","cite":"148 U.S. 312","y":1893,"id":"scdb/1892-151","sc":1,"ar":1,"sum":"In the proceedings taken under the act of August 11, 1888, 25 Stafc.pp. 400, 411, c. 860, to condemn lock and dam No. 7 of the Monongahela Navigation Company, that company is entitled under the provisions of the Fifth Amendment to the Constitution, to recover compensation from the United States for the taking of the franchise to exact tolls, as well as for the value of the tangible property taken.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"15, 31","2":"12"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13, 14"}},{"t":"case","label":"NAACP v. Federal Power Comm’n","cite":"425 U.S. 662","y":1976,"id":"1975/74-1608","sc":1,"sum":"The National Association for the Advancement of Colored People and various other organizations petitioned the Fcderal Power Commission (FPC) to issue a rule \"requiring equal employment opportunity and nondiscrimination in the employment practices of its regulatees.\" The FPC refused, holding that it had no Jurisdiction to issue such a rule. On petition for review, the Court of Appeals, while agreeing that the FPC …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32, 48"}},{"t":"case","label":"Nebraska v. United States","cite":"164 F.2d 866","y":1947,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/164/866/","by":{"1":"20"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"593 U.S. 155","y":2021,"id":"2020/19-863","sc":1,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"34"}},{"t":"case","label":"Northwest Airlines, Inc. v. Transport Workers Union of Am.","cite":"451 U.S. 77","y":1981,"id":"1980/79-1056","sc":1,"sum":"Petitioner has neither a federal statutory nor a federal common-law right to contribution from respondent unions.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"12, 46"}},{"t":"case","label":"Pension Ben. Guar. Corp. v. LTV Corp.","cite":"496 U.S. 633","y":1990,"id":"1989/89-390","sc":1,"sum":"The PBGC's restoration decision was not arbitrary and capricious or contrary to law under § 706(2)(A).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Peter v. NantKwest, Inc.","cite":"589 U.S. 23","y":2019,"id":"2019/18-801","sc":1,"sum":"The Court held that the phrase “[a]ll the expenses of the proceedings” in 35 U.S.C. § 145 does not include attorneys’ fees incurred as a result of defending the agency in § 145 litigation.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Rodriguez v. Federal Deposit Ins. Corp.","cite":"589 U.S. 132","y":2020,"id":"2019/18-1269","sc":1,"sum":"A case in which the Court vacated the ruling below that had applied a federal common-law rule on how to allocate a tax refund paid to an affiliated group.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Ruckelshaus v. Sierra Club","cite":"463 U.S. 680","y":1983,"id":"1982/82-242","sc":1,"sum":"Absent some degree of success on the merits by the claimant, it is not \"appropriate\" for a federal court to award attorney's fees under §307(f).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1984,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25","3":"17, 18"}},{"t":"case","label":"Sabal Trail Transmission, LLC v. 3.921 Acres of Land","cite":"74 F.4th 1346","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/74/1346/","by":{"1":"13, 27","2":"16, 32"}},{"t":"case","label":"SAS Inst., Inc. v. Iancu","cite":"584 U.S. 357","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Schneidewind v. ANR Pipeline Co.","cite":"485 U.S. 293","y":1988,"id":"1987/86-986","sc":1,"sum":"The MPSC regulation of respondents through Act 144 impinges on a field that the federal regulatory scheme has occupied to the exclusion of state law, and Act 144 therefore is pre-empted.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4","2":"32"}},{"t":"case","label":"Simpson v. Shepard (Minnesota Rate Cases)","cite":"230 U.S. 352","y":1913,"id":"scdb/1912-290","sc":1,"sum":"— Decided June 9, 1913.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"United States ex rel. Tennessee Valley Auth. v. Powelson","cite":"319 U.S. 266","y":1943,"id":"scdb/1942-061","sc":1,"sum":"(1) That in order to permit consideration of such special adapta, bility th,,re must be a reasonable probability of the condemned tract's being thus combined with other tracts in the near future, otherwise the special use would be too remote and speculative to have any legitimate effect upon the valuation. P. 275. (2) The landowner's privilege to use the power of eminent domain-granted by the State in which the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16, 17, 19","2":"21"}},{"t":"case","label":"Transwestern Pipeline Co. v. 17.19 Acres of Prop.","cite":"627 F.3d 1268","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/627/1268/","by":{"1":"23, 44","3":"20, 21"}},{"t":"case","label":"United States v. 13,255.53 Acres of Land","cite":"158 F.2d 874","y":1946,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/158/874/","by":{"1":"20"}},{"t":"case","label":"United States v. 19.86 Acres of Land","cite":"141 F.2d 344","y":1944,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/141/344/","by":{"1":"20"}},{"t":"case","label":"United States v. 564.54 Acres of Land","cite":"441 U.S. 506","y":1979,"id":"1978/78-488","sc":1,"sum":"Allowing respondent the fair market value of its property, rather than the cost of substitute facilities, is consistent with the principles of fairness underlying the Just Compensation Clause of the Fifth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15, 17, 31, 32"}},{"t":"case","label":"United States v. 93.970 Acres of Land","cite":"360 U.S. 328","y":1959,"id":"1958/573","sc":1,"sum":"Under a statute authorizing the Secretary of the Navy to lease naval lands under revocable leases, he leased a naval airfield in Illinois to a private operator. The lease contained a preamble stating that it was considered essential to retain the field in a stand-by status for use \"in connection with Naval Aviation activities\" and a substantive provision that \"this lease will at all times be revocable at will by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22, 39, 41, 43","2":"14, 15, 18","3":"9, 10"}},{"t":"case","label":"United States v. Certain Parcels of Land in Philadelphia","cite":"145 F.2d 374","y":1944,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/145/374/","by":{"1":"20"}},{"t":"case","label":"United States v. Chandler-Dunbar Water Power Co.","cite":"229 U.S. 53","y":1913,"id":"scdb/1912-214","sc":1,"sum":"The technical title to the beds of navigable rivers of the United States is either in the States in which the rivers are situated, or in the riparian owners, depending upon the local law.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"20, 21"}},{"t":"case","label":"United States v. Cors","cite":"337 U.S. 325","y":1949,"id":"scdb/1948-092","sc":1,"sum":"It erred in doing so.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"United States v. Dow","cite":"357 U.S. 17","y":1958,"id":"1957/102","sc":1,"sum":"The \"taking\" occurred in 1943 when the Government entered into physical possession of the land; the assignment of the claim for compensation was invalid under the Assignment of Claims Act; and the respondent was not entitled to receive the compensation award.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"United States v. Johnson","cite":"529 U.S. 53","y":2000,"id":"1999/98-1696","sc":1,"sum":"The Court held that the length of a supervised release term cannot be reduced by reason of excess time served in prison.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"United States v. Jones","cite":"109 U.S. 513","y":1883,"id":"scdb/1883-070","sc":1,"sum":"Conflict of Laws — Constitutional Law — Damages—JEminent Domain — State Courts.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"3, 13, 15","3":"7, 8, 22"}},{"t":"case","label":"United States v. Jotham Bixby Co.","cite":"55 F.2d 317","y":1932,"court":"S.D. Cal.","url":"https://www.courtlistener.com/c/F.2d/55/317/","by":{"1":"40"}},{"t":"case","label":"United States v. New River Collieries Co.","cite":"262 U.S. 341","y":1923,"id":"scdb/1922-196","sc":1,"sum":"1. Under § 10 of-the Lever Act and the Fifth Amendment, the owner of property requisitioned by the United States is entitled to the full money equivalent of the property taken; and the ascertainment of this just compensation is a judicial function.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Wilson v. Garcia","cite":"471 U.S. 261","y":1985,"id":"1984/83-2146","sc":1,"sum":"The Court held that, in situations where a federal action does not have a statute of limitations, the practice has been to adopt a local limitation as long as that limitation is not inconsistent with a federal law or policy.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Ysleta Del Sur Pueblo v. Texas","cite":"596 U.S. 685","y":2022,"id":"2021/20-493","sc":1,"sum":"The federal legislation at issue—the Ysleta del Sur and Alabama and Coushatta Indian Tribes of Texas Restoration Act—bans as a matter of federal law on tribal lands only those gaming activities also banned in Texas.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"18"}},{"t":"usc","label":"15 U.S.C. § 717a","url":"https://www.law.cornell.edu/uscode/text/15/717a","by":{"1":"6"}},{"t":"usc","label":"25 U.S.C. § 640d-14","url":"https://www.law.cornell.edu/uscode/text/25/640d-14","subs":["(b)(2)"],"by":{"1":"24"}},{"t":"usc","label":"28 U.S.C. § 2412","url":"https://www.law.cornell.edu/uscode/text/28/2412","subs":["(a)(1)","(d)(1)(A)","(d)(2)(H)"],"stext":{"head":"§2412. Costs and fees","paras":[[0,"(a)(1) Except as otherwise specifically provided by statute, a judgment for costs, as enumerated in section 1920 of this title, but not including the fees and expenses of attorneys, may be awarded to the prevailing party in any civil action brought by or against the United States or any agency or any official of the United States acting in his or her official capacity in any court having jurisdiction of such action. A judgment for costs when taxed against the United States shall, in an amount established by statute, court rule, or order, be limited to reimbursing in whole or in part the prevailing party for the costs incurred by such party in the litigation."],[0,"(2) A judgment for costs, when awarded in favor of the United States in an action brought by the United States, may include an amount equal to the filing fee prescribed under section 1914(a) of this title. The preceding sentence shall not be construed as requiring the United States to pay any filing fee."],[0,"(b) Unless expressly prohibited by statute, a court may award reasonable fees and expenses of attorneys, in addition to the costs which may be awarded pursuant to subsection (a), to the prevailing party in any civil action brought by or against the United States or any agency or any official of the United States acting in his or her official capacity in any court having jurisdiction of such action. The United States shall be liable for such fees and expenses to the same extent that any other party would be liable under the common law or under the terms of any statute which specifically provides for such an award."],[0,"(c)(1) Any judgment against the United States or any agency and any official of the United States acting in his or her official capacity for costs pursuant to subsection (a) shall be paid as provided in sections 2414 and 2517 of this title and shall be in addition to any relief provided in the judgment."],[0,"(2) Any judgment against the United States or any agency and any official of the United States acting in his or her official capacity for fees and expenses of attorneys pursuant to subsection (b) shall be paid as provided in sections 2414 and 2517 of this title, except that if the basis for the award is a finding that the United States acted in bad faith, then the award shall be paid by any agency found to have acted in bad faith and shall be in addition to any relief provided in the judgment."],[0,"(d)(1)(A) Except as otherwise specifically provided by statute, a court shall award to a prevailing party other than the United States fees and other expenses, in addition to any costs awarded pursuant to subsection (a), incurred by that party in any civil action (other than cases sounding in tort), including proceedings for judicial review of agency action, brought by or against the United States in any court having jurisdiction of that action, unless the court finds that the position of the United States was substantially justified or that special circumstances make an award unjust."],[0,"(B) A party seeking an award of fees and other expenses shall, within thirty days of final judgment in the action, submit to the court an application for fees and other expenses which shows that the party is a prevailing party and is eligible to receive an award under this subsection, and the amount sought, including an itemized statement from any attorney or expert witness representing or appearing in behalf of the party stating the actual time expended and the rate at which fees and other expenses were computed. The party shall also allege that the position of the United States was not substantially justified. Whether or not the position of the United States was substantially justified shall be determined on the basis of the record (including the record with respect to the action or failure to act by the agency upon which the civil action is based) which is made in the civil action for which fees and other expenses are sought."],[0,"(C) The court, in its discretion, may reduce the amount to be awarded pursuant to this subsection, or deny an award, to the extent that the prevailing party during the course of the proceedings engaged in conduct which unduly and unreasonably protracted the final resolution of the matter in controversy."],[0,"(D) If, in a civil action brought by the United States or a proceeding for judicial review of an adversary adjudication described in section 504(a)(4) of title 5, the demand by the United States is substantially in excess of the judgment finally obtained by the United States and is unreasonable when compared with such judgment, under the facts and circumstances of the case, the court shall award to the party the fees and other expenses related to defending against the excessive demand, unless the party has committed a willful violation of law or otherwise acted in bad faith, or special circumstances make an award unjust. Fees and expenses awarded under this subparagraph shall be paid only as a consequence of appropriations provided in advance."],[0,"(2) For the purposes of this subsection—"],[1,"(A) \"fees and other expenses\" includes the reasonable expenses of expert witnesses, the reasonable cost of any study, analysis, engineering report, test, or project which is found by the court to be necessary for the preparation of the party's case, and reasonable attorney fees (The amount of fees awarded under this subsection shall be based upon prevailing market rates for the kind and quality of the services furnished, except that (i) no expert witness shall be compensated at a rate in excess of the highest rate of compensation for expert witnesses paid by the United States; and (ii) attorney fees shall not be awarded in excess of $125 per hour unless the court determines that an increase in the cost of living or a special factor, such as the limited availability of qualified attorneys for the proceedings involved, justifies a higher fee.);"],[1,"(B) \"party\" means (i) an individual whose net worth did not exceed $2,000,000 at the time the civil action was filed, or (ii) any owner of an unincorporated business, or any partnership, corporation, association, unit of local government, or organization, the net worth of which did not exceed $7,000,000 at the time the civil action was filed, and which had not more than 500 employees at the time the civil action was filed; except that an organization described in section 501(c)(3) of the Internal Revenue Code of 1986 (26 U.S.C. 501(c)(3)) exempt from taxation under section 501(a) of such Code, or a cooperative association as defined in section 15(a) of the Agricultural Marketing Act (12 U.S.C. 1141j(a)), may be a party regardless of the net worth of such organization or cooperative association or for purposes of subsection (d)(1)(D), a small entity as defined in section 601 of title 5;"],[1,"(C) \"United States\" includes any agency and any official of the United States acting in his or her official capacity;"],[1,"(D) \"position of the United States\" means, in addition to the position taken by the United States in the civil action, the action or failure to act by the agency upon which the civil action is based; except that fees and expenses may not be awarded to a party for any portion of the litigation in which the party has unreasonably protracted the proceedings;"],[1,"(E) \"civil action brought by or against the United States\" includes an appeal by a party, other than the United States, from a decision of a contracting officer rendered pursuant to a disputes clause in a contract with the Government or pursuant to chapter 71 of title 41;"],[1,"(F) \"court\" includes the United States Court of Federal Claims and the United States Court of Appeals for Veterans Claims;"],[1,"(G) \"final judgment\" means a judgment that is final and not appealable, and includes an order of settlement;"],[1,"(H) \"prevailing party\", in the case of eminent domain proceedings, means a party who obtains a final judgment (other than by settlement), exclusive of interest, the amount of which is at least as close to the highest valuation of the property involved that is attested to at trial on behalf of the property owner as it is to the highest valuation of the property involved that is attested to at trial on behalf of the Government; and"],[1,"(I) \"demand\" means the express demand of the United States which led to the adversary adjudication, but shall not include a recitation of the maximum statutory penalty (i) in the complaint, or (ii) elsewhere when accompanied by an express demand for a lesser amount."],[0,"(3) In awarding fees and other expenses under this subsection to a prevailing party in any action for judicial review of an adversary adjudication, as defined in subsection (b)(1)(C) of section 504 of title 5, or an adversary adjudication subject to chapter 71 of title 41, the court shall include in that award fees and other expenses to the same extent authorized in subsection (a) of such section, unless the court finds that during such adversary adjudication the position of the United States was substantially justified, or that special circumstances make an award unjust."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2412?type=usc&year=mostrecent&link-type=html"},"head":"§2412. Costs and fees","tname":"Judiciary and Judicial Procedure","by":{"1":"23","2":"13, 13"}},{"t":"usc","label":"33 U.S.C. § 532","url":"https://www.law.cornell.edu/uscode/text/33/532","stext":{"head":"§532. Eminent domain","paras":[[0,"There are conferred upon any individual, his heirs, legal representatives, or assigns, any firm or corporation, its successors or assigns, or any State, political subdivision, or municipality authorized in accordance with the provisions of this subchapter to build a bridge between two or more States, all such rights and powers to enter upon lands and acquire, condemn, occupy, possess, and use real estate and other property in the respective States needed for the location, construction, operation, and maintenance of such bridge and its approaches, as are possessed by railroad corporations for railroad purposes or by bridge corporations for bridge purposes in the State in which such real estate or other property is situated, upon making just compensation therefor to be ascertained and paid according to the laws of such State, and the proceedings therefor shall be the same as in the condemnation or expropriation of property for public purposes in such State."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/532?type=usc&year=mostrecent&link-type=html"},"head":"§532. Eminent domain","tname":"Navigation and Navigable Waters","by":{"1":"2","2":"14, 18","3":"18"}},{"t":"usc","label":"42 U.S.C. § 1988","url":"https://www.law.cornell.edu/uscode/text/42/1988","by":{"1":"42"}},{"t":"usc","label":"43 U.S.C. § 945a","url":"https://www.law.cornell.edu/uscode/text/43/945a","by":{"1":"24"}},{"t":"law","label":"Act to Amend the Natural Gas Act, Pub. L. No. 80-245","by":{"1":"6"}},{"t":"law","label":"Pub. L. No. 109-58","url":"https://www.govinfo.gov/link/plaw/109/public/58","by":{"1":"25","2":"30"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"(III) Cases—Continued: Alyeska Pipeline Serv. Co. v. Wilderness Soc’y","cite":"421 U.S. 240","y":1975,"id":"1974/73-1977","sc":1,"sum":"Under the \"American Rule\" that attorneys' fees are not ordinarily recoverable by the prevailing litigant in federal litigation in the absence of statutory authorization, respondents, which had instituted litigation to prevent issuance of Government permits required for construction of the trans-Alaska oil pipeline, cannot recover attorneys' fees from petitioner based on the \"private attorney general\" approach …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"Burks v. Lasker","cite":"441 U.S. 471","y":1979,"id":"1978/77-1724","sc":1,"sum":"In suits alleging violations of the ICA and IAA, federal courts should, as a matter of federal law, apply state law governing the authority of independent directors to discontinue derivative suits to the extent such law is consistent with the policies of the ICA and the IAA. Congress did not require that States, or federal courts, absolutely forbid director termination of all nonfrivolous actions.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25","3":"4"}},{"t":"case","label":"Dolan v. City of Tigard","cite":"512 U.S. 374","y":1994,"id":"1993/93-518","sc":1,"sum":"The city's dedication requirements constitute an uncompensated taking of property.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"Holmberg v. Armbrecht","cite":"327 U.S. 392","y":1946,"id":"scdb/1945-049","sc":1,"sum":"1. Decision of a suit in a federal court to enforce a federally created equitable right is not controlled by the statute of limitations of the State of the forum. Guaranty Trust Co. v. York, 326 U. S. 99, distinguished. Accordingly, a class suit by creditors of a joint stock land bank to enforce the liability imposed upon shareholders of the bank by § 16 of the Federal Farm Loan Act is not barred by the state …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"26","3":"4"}},{"t":"case","label":"Jama v. ICE","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"2":"27, 28"}},{"t":"case","label":"Johnson v. Transportation Agency","cite":"480 U.S. 616","y":1987,"id":"1986/85-1129","sc":1,"sum":"The Court affirmed the promotion procedures of the Agency. Justice Brennan argued that it was not unreasonable to consider sex as one factor among many in making promotion decisions, and that the Agency's actions did not create an absolute barrier to the advancement of men (a quota system did not exist).","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"Lackey v. Stinnie","cite":"604 U.S. 192","y":2025,"id":"2024/23-621","sc":1,"sum":"Plaintiffs who gained only preliminary injunctive relief before this action became moot do not qualify as “prevailing part[ies]” eligible for attorney’s fees under 42 U. S. C. §1988(b) because no court conclusively resolved their claims by granting enduring relief on the merits that altered the legal relationship between the parties.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"29"}},{"t":"case","label":"Pung v. Isabella County","cite":"146 S. Ct. 1964","y":2026,"id":"2025/25-95","sc":1,"sum":"The proper baseline for measuring “just compensation” following a fairly conducted tax sale is the auction sale price, not the property’s hypothetical fair market value; Isabella County did not violate the Eighth Amendment Excessive Fines Clause by failing to compensate the taxpayer for his property’s fair market value.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"12"}},{"t":"case","label":"Ruckelshaus v. Monsanto Co.","cite":"467 U.S. 986","y":1984,"id":"1983/83-196","sc":1,"sum":"The Federal Insecticide, Fungicide, and Rodenticide Act (FIFRA) authorizes the Environmental Protection Agency (EPA) to use data submitted by an applicant for registration of a covered product (hereinafter pesticide) in evaluating the application of a subsequent applicant, and to disclose publicly some of the submitted data. Under the dataconsideration provisions of § 3, as amended in 1978, applicants now are …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"United States v. 50 Acres of Land","cite":"469 U.S. 24","y":1984,"id":"1984/83-1170","sc":1,"sum":"The Fifth Amendment does not require that the United States pay a public condemnee compensation measured by the cost of acquiring a substitute facility that the condemnee has a duty to acquire, when the market value of the condemned property is ascertainable and when there is no showing of manifest injustice.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12"}},{"t":"case","label":"United States v. Reynolds","cite":"397 U.S. 14","y":1970,"id":"1969/88","sc":1,"sum":"The Supreme Court held that Federal Rule of Civil Procedure 71A(h) provides that the jury is limited to deciding amount of just compensation. The trial judge should decide all other issues. The Court also briefly confirmed that the scope of the project includes any land that will likely be used according to early plans.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"2":"13"}},{"t":"law","label":"Equal Access to Justice Act, Pub. L. No. 96-481","url":"https://www.govinfo.gov/link/statute/94/2325","by":{"2":"13"}},{"t":"usc","label":"16 U.S.C. § 791a","url":"https://www.law.cornell.edu/uscode/text/16/791a","by":{"2":"5"}},{"t":"usc","label":"33 U.S.C. § 525","url":"https://www.law.cornell.edu/uscode/text/33/525","by":{"2":"14"}},{"t":"usc","label":"15 U.S.C. § 717","url":"https://www.law.cornell.edu/uscode/text/15/717","subs":["(a)","(b)"],"by":{"2":"1, 4, 33, 4"}},{"t":"usc","label":"42 U.S.C. § 4654","url":"https://www.law.cornell.edu/uscode/text/42/4654","subs":["(a)","(a)(1)","(a)(2)"],"by":{"2":"29, 13, 13"}},{"t":"reg","label":"Exec. Order No. 14,154, Unleashing American Energy, 90 Fed. Reg. 8353","url":"https://www.govinfo.gov/link/fr/90/8353","by":{"2":"33"}},{"t":"reg","label":"Exec. Order No. 14,156, Declaring a National Energy Emergency, 90 Fed. Reg. 8433","url":"https://www.govinfo.gov/link/fr/90/8433","by":{"2":"33"}},{"t":"reg","label":"82 Fed. Reg. 60,007","url":"https://www.govinfo.gov/link/fr/82/60007","by":{"2":"6"}},{"t":"case","label":"Bank of Am. Nat. Tr. & Sav. Ass’n v. Parnell","cite":"352 U.S. 29","y":1956,"id":"1956/21","sc":1,"sum":"The judgment of the Court of Appeals is reversed and the case is remanded to that Court for further proceedings.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"10"}},{"t":"case","label":"Chevron Oil Co. v. Huson","cite":"404 U.S. 97","y":1971,"id":"1971/70-11","sc":1,"sum":"The Supreme Court held that Louisiana's statute of limitations was applicable under the Outer Continental Shelf Lands Act because the Lands Act specifically adopted relevant state laws as federal laws. There was no federal statute of limitations specified in the Lands Act so, state law was not inconsistent.","sumSrc":"Oyez","by":{"3":"3"}},{"t":"case","label":"Clearfield Tr. Co. v. United States","cite":"318 U.S. 363","y":1943,"id":"scdb/1942-110","sc":1,"ar":2,"by":{"3":"10"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"3":"22"}},{"t":"case","label":"Geier v. Am. Honda Motor Co.","cite":"529 U.S. 861","y":2000,"id":"1999/98-1811","sc":1,"sum":"The Court held that \"[Geier's] 'no airbag' lawsuit conflicts with the objectives of FMVSS 208 and is therefore pre-empted by the Act.\" Justice Breyer wrote for the Court that a rule of state tort law imposing a duty to install airbags in cars such as Honda's would have presented an obstacle to the variety and mix of devices that the federal regulation sought and to the phase-in that the federal regulation deliberately imposed.","sumSrc":"Oyez","by":{"3":"15"}},{"t":"case","label":"Gross v. FBL Fin. Servs., Inc.","cite":"557 U.S. 167","y":2009,"id":"2008/08-441","sc":1,"sum":"The Court held that a plaintiff must show that age was the \"but-for\" cause for the defendant's action in an Age Discrimination in Employment Act claim.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"Hencely v. Fluor Corp.","cite":"146 S. Ct. 1086","y":2026,"id":"2025/24-924","sc":1,"ar":4,"sum":"The Court of Appeals for the Fourth Circuit erred in finding Winston Hencely’s state-law tort claims preempted where the Federal Government neither ordered nor authorized Fluor Corporation’s challenged conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"6"}},{"t":"case","label":"Jerman v. Carlisle, McNellie, Rini, Kramer & Ulrich, L.P.A.","cite":"559 U.S. 573","y":2010,"id":"2009/08-1200","sc":1,"sum":"The Court held that a debt collector's mistake in interpreting the law cannot qualify for the Fair Debt Collection Practices Act bona fide error defense.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Lindh v. Murphy","cite":"521 U.S. 320","y":1997,"id":"1996/96-6298","sc":1,"sum":"The Court held that the 1996 version of the federal habeas statute, as to standards affecting the entitlement of state prisoners to federal habeas corpus relief, does not to apply to non-capital habeas corpus cases that were pending when the Act was enacted.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"Monroe v. Pape","cite":"365 U.S. 167","y":1961,"id":"1960/39","sc":1,"sum":"Yes and No. Justice William O. Douglas, writing for the majority, stated that the city police officers, in conducting an unreasonable search and seizure, had committed an action which was under the color of law, and that the police could be held liable individually under the Civil Rights Act. However, the majority further held that a municipality could not be liable under the Civil Rights Act.","sumSrc":"Oyez","by":{"3":"4"}},{"t":"case","label":"N.Y. Cent. R.R. Co. v. Winfield","cite":"244 U.S. 147","y":1917,"id":"scdb/1916-068","sc":1,"sum":"The liabilities and obligations of interstate railroad carriers to make compensation for personal injuries suffered by their employees while engaged in interstate commerce are regulated both inclusively and exclusively by the Federal Employers’ Liability Act; and, Congress having thus fully covered the subject, no room exists for state regulation, even in respect of injuries occurring without fault, as to which the …","sumSrc":"Headnote (U.S. Reports)","by":{"3":"5"}},{"t":"case","label":"North Dakota v. United States","cite":"495 U.S. 423","y":1990,"id":"1989/88-926","sc":1,"sum":"The judgment is reversed. 856 F. 2d 1107, reversed. JUSTICE STEVENS, joined by THE CHIEF JUSTICE, JUSTICE WHITE, and JUSTICE O'CONNOR, concluded that the state regulations are not invalid under the Supremacy Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"2, 3, 6, 9, 15"}},{"t":"usc","label":"28 U.S.C. § 1491","url":"https://www.law.cornell.edu/uscode/text/28/1491","by":{"3":"12"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"3":"4, 5"}}]};